  select distinct on (i.id)
         profile, i.id, i.name, coalesce(i.symbol, 'list.bullet'), coalesce(i.position, 0), i.created_at,
         coalesce(i.is_removed, false), i.updated_at
  from jsonb_to_recordset(items) as i (
